extern printf(fmt: string, ...);

struct User {
    name: string,
    email: string,
    score: int,
}

frame getGrade(score: int) ret string {
    if (score >= 90) { return "A"; }
    if (score >= 80) { return "B"; }
    if (score >= 70) { return "C"; }
    if (score >= 60) { return "D"; }
    return "F";
}

frame formatUser(u: *User) ret string {
    local grade: string = getGrade(u.score);
    return "User: ${u.name} <${u.email}> - Score: ${u.score} (Grade: ${grade})";
}

frame main() ret int {
    local users: User[] = [
        User { name: "Alice", email: "alice@example.com", score: 95 },
        User { name: "Bob", email: "bob@example.com", score: 82 },
        User { name: "Carol", email: "carol@example.com", score: 67 }
    ];

    printf("=== User Report ===\n\n");

    loop (local i: int = 0; i < 3; i = i + 1) {
        local report: string = formatUser(&users[i]);
        printf("%s\n", report);
    }

    return 0;
}

extern printf(fmt: string, ...);

frame main() ret int {
    local name: string = "Alice";
    local score: int = 95;
    local gpa: float = 3.8;

    # Printf style - format specifiers required
    printf("Printf: %s scored %d with GPA %.1f\n", name, score, gpa);

    # Interpolation - clearer, inline
    local msg: string = "Interp: ${name} scored ${score} with GPA ${gpa}";
    printf("%s\n", msg);

    # Printf advantage: formatting control
    printf("Formatted: %10s | %5d | %6.2f\n", name, score, gpa);

    # Both have their place!
    # - Printf: when you need precise formatting
    # - Interpolation: for readable string building

    return 0;
}

