extern printf(fmt: string, ...);

frame formatLog(level: string, msg: string, code: int) {
    printf("[%s] %s (code: %d)\n", level, msg, code);
}

frame main() ret int {
    formatLog("INFO", "Started", 0);
    formatLog("ERROR", "Failed", 500);
    formatLog("WARN", "Retrying", 503);

    return 0;
}
